;
; CASM Phase 10 WP51 listing capture: two conditional VMM stores (a fixed
; 16-byte metadata record per captured physical source line, and a mirror of
; every Pass 2 source-generated byte), plus replay for WP53's later
; serializer. `/L` remains rejected by production orchestration until WP54;
; this module writes no `.LST` file and is never called in production yet.
;
; WP51 increment 3 scope: allocation (listingCaptureInit), the metadata
; append/replay primitives, and enough lifecycle state (listingStateInit) to
; exercise both in isolation through test_casm_listing. The per-line
; transaction API (listingBeginLine/listingMirrorByte/listingCommitLine/
; listingCaptureFinalize) and the byte-mirror stage arrive in increment 4;
; emitter/pass/include integration in increment 5.

.include "command64.inc"
.include "common.inc"

.import vmmStoreAlloc
.import vmmWindowRead
.import vmmWindowWrite
.import CasmVmmBuffer
.import sourceSetLineCapture

.export listingStateInit
.export listingCaptureInit
.export listingMetaAppend
.export listingReplayReset
.export listingReplayNext
.export CasmListingState
.export CasmListingMetaVmmSlot
.export CasmListingByteVmmSlot
.export CasmListingRecordCountLo
.export CasmListingRecordCountHi
.export CasmListingPendingFileId
.export CasmListingPendingFlags
.export CasmListingPendingLineLo
.export CasmListingPendingLineHi
.export CasmListingPendingOffsetLo
.export CasmListingPendingOffsetHi
.export CasmListingPendingLen
.export CasmListingPendingPcLo
.export CasmListingPendingPcHi
.export CasmListingPendingByteOffLo
.export CasmListingPendingByteOffHi
.export CasmListingPendingByteCountLo
.export CasmListingPendingByteCountHi

.segment "BSS"

CasmListingState:         .res 1
CasmListingMetaVmmSlot:   .res 1
CasmListingByteVmmSlot:   .res 1
CasmListingRecordCountLo: .res 1
CasmListingRecordCountHi: .res 1
CasmListingReplayIndexLo: .res 1
CasmListingReplayIndexHi: .res 1

; Metadata record fields, staged by the caller before listingMetaAppend.
; Reserved0/Reserved1 are not staged here at all -- listingMetaAppend always
; zero-fills the whole 16-byte record first, so reserved bytes are always
; zero regardless of whatever a prior append left in CasmVmmBuffer.
CasmListingPendingFileId:      .res 1
CasmListingPendingFlags:       .res 1
CasmListingPendingLineLo:      .res 1
CasmListingPendingLineHi:      .res 1
CasmListingPendingOffsetLo:    .res 1
CasmListingPendingOffsetHi:    .res 1
CasmListingPendingLen:         .res 1
CasmListingPendingPcLo:        .res 1
CasmListingPendingPcHi:        .res 1
CasmListingPendingByteOffLo:   .res 1
CasmListingPendingByteOffHi:   .res 1
CasmListingPendingByteCountLo: .res 1
CasmListingPendingByteCountHi: .res 1

.segment "CODE"

; ---------------------------------------------------------------------------
; listingStateInit
; Clear listing state to NONE without acquiring any resource. Safe to call
; unconditionally from normal CASM initialization so every listing hook stays
; a deterministic no-op while `/L` is rejected in production.
;
; Inputs:    none
; Outputs:   A = CASM_DIAG_NONE, C clear
; Clobbers:  A
; ---------------------------------------------------------------------------
listingStateInit:
    lda #CASM_LISTING_STATE_NONE
    sta CasmListingState
    lda #0
    sta CasmListingRecordCountLo
    sta CasmListingRecordCountHi
    sta CasmListingReplayIndexLo
    sta CasmListingReplayIndexHi
    lda #CASM_DIAG_NONE
    clc
    rts

; ---------------------------------------------------------------------------
; listingCaptureInit
; Allocate both listing VMM stores (65,535 bytes requested each; vmmStoreAlloc
; rounds each up to a granted 65,536-byte, 16-page allocation) and enable
; source-side line capture. Requires CasmListingState == NONE (a fresh
; listingStateInit, not yet initialized for capture).
;
; A second-allocation failure leaves the first store's registry slot
; untouched: central cleanup (resources.s's registry sweep) owns releasing
; it, matching the symbol table's and relocation table's own established
; precedent of never freeing a VMM allocation explicitly outside that sweep.
;
; Inputs:    CasmListingState == CASM_LISTING_STATE_NONE
; Outputs:   Success: A = CASM_DIAG_NONE, C clear; both slots recorded;
;            record/replay counters zeroed; source capture enabled;
;            CasmListingState = CASM_LISTING_STATE_ENABLED
;            Failure: A = CASM_DIAG_STREAM_STATE_FAILED (wrong starting
;            state) or an existing VMM diagnostic (CASM_DIAG_VMM_UNAVAILABLE/
;            CASM_DIAG_VMM_ALLOC_FAILED) propagated from vmmStoreAlloc,
;            C set; CasmListingState unchanged
; Clobbers:  A, X, Y, CasmValue0Lo/Hi (via vmmStoreAlloc)
; ---------------------------------------------------------------------------
listingCaptureInit:
    lda CasmListingState
    cmp #CASM_LISTING_STATE_NONE
    beq lciStateOk
    lda #CASM_DIAG_STREAM_STATE_FAILED
    sec
    rts
lciStateOk:
    ldx #<$FFFF
    ldy #>$FFFF
    jsr vmmStoreAlloc
    bcs lciRet
    stx CasmListingMetaVmmSlot

    ldx #<$FFFF
    ldy #>$FFFF
    jsr vmmStoreAlloc
    bcs lciRet
    stx CasmListingByteVmmSlot

    lda #0
    sta CasmListingRecordCountLo
    sta CasmListingRecordCountHi
    sta CasmListingReplayIndexLo
    sta CasmListingReplayIndexHi

    lda #1
    jsr sourceSetLineCapture

    lda #CASM_LISTING_STATE_ENABLED
    sta CasmListingState
    lda #CASM_DIAG_NONE
    clc
lciRet:
    rts

; ---------------------------------------------------------------------------
; listingMetaAppend
; Append one 16-byte metadata record from the CasmListingPending* staging
; fields. Zero-fills the record first, so Reserved0/Reserved1 are always
; zero regardless of any prior append's leftover CasmVmmBuffer content.
;
; Inputs:    CasmListingPendingFileId/Flags/LineLo/Hi/OffsetLo/Hi/Len/PcLo/Hi/
;            ByteOffLo/Hi/ByteCountLo/Hi staged by the caller
; Outputs:   Success: C clear; record written at index
;            CasmListingRecordCountLo/Hi (before increment), count
;            incremented
;            Failure: A = CASM_DIAG_LISTING_RECORDS_FULL (count already at
;            CASM_LISTING_META_MAX) or CASM_DIAG_VMM_TRANSFER_FAILED, C set;
;            count unchanged
; Clobbers:  A, X, Y, CasmVmmBuffer, CasmVmmOffLo/OffHi, CasmIoLenLo/Hi
; ---------------------------------------------------------------------------
listingMetaAppend:
    lda CasmListingRecordCountHi
    cmp #>CASM_LISTING_META_MAX
    bne lmaNotFull
    lda CasmListingRecordCountLo
    cmp #<CASM_LISTING_META_MAX
    bne lmaNotFull
    lda #CASM_DIAG_LISTING_RECORDS_FULL
    sec
    rts
lmaNotFull:
    ldy #CASM_LISTING_META_REC_SIZE - 1
    lda #0
lmaZeroLoop:
    sta CasmVmmBuffer, y
    dey
    bpl lmaZeroLoop

    lda CasmListingPendingFileId
    sta CasmVmmBuffer + CASM_LISTING_META_FILEID
    lda CasmListingPendingFlags
    sta CasmVmmBuffer + CASM_LISTING_META_FLAGS
    lda CasmListingPendingLineLo
    sta CasmVmmBuffer + CASM_LISTING_META_LINE_LO
    lda CasmListingPendingLineHi
    sta CasmVmmBuffer + CASM_LISTING_META_LINE_HI
    lda CasmListingPendingOffsetLo
    sta CasmVmmBuffer + CASM_LISTING_META_OFF_LO
    lda CasmListingPendingOffsetHi
    sta CasmVmmBuffer + CASM_LISTING_META_OFF_HI
    lda CasmListingPendingLen
    sta CasmVmmBuffer + CASM_LISTING_META_LEN
    lda CasmListingPendingPcLo
    sta CasmVmmBuffer + CASM_LISTING_META_PC_LO
    lda CasmListingPendingPcHi
    sta CasmVmmBuffer + CASM_LISTING_META_PC_HI
    lda CasmListingPendingByteOffLo
    sta CasmVmmBuffer + CASM_LISTING_META_BYTEOFF_LO
    lda CasmListingPendingByteOffHi
    sta CasmVmmBuffer + CASM_LISTING_META_BYTEOFF_HI
    lda CasmListingPendingByteCountLo
    sta CasmVmmBuffer + CASM_LISTING_META_BYTECOUNT_LO
    lda CasmListingPendingByteCountHi
    sta CasmVmmBuffer + CASM_LISTING_META_BYTECOUNT_HI

    ; VMM offset = record index * 16 (16-bit left shift by 4).
    lda CasmListingRecordCountLo
    sta CasmVmmOffLo
    lda CasmListingRecordCountHi
    sta CasmVmmOffHi
    ldx #4
lmaShift:
    asl CasmVmmOffLo
    rol CasmVmmOffHi
    dex
    bne lmaShift

    lda #CASM_LISTING_META_REC_SIZE
    sta CasmIoLenLo
    lda #0
    sta CasmIoLenHi
    ldx CasmListingMetaVmmSlot
    jsr vmmWindowWrite
    bcs lmaRet

    inc CasmListingRecordCountLo
    bne lmaDone
    inc CasmListingRecordCountHi
lmaDone:
    clc
lmaRet:
    rts

; ---------------------------------------------------------------------------
; listingReplayReset
; Reset the metadata replay cursor to the first record. Requires complete
; capture (CasmListingState == COMPLETE) -- WP53's serializer replays only
; after Pass 2 agreement and PRG finalization succeed.
;
; Inputs:    CasmListingState == CASM_LISTING_STATE_COMPLETE
; Outputs:   Success: A = CASM_DIAG_NONE, C clear; replay cursor = 0
;            Failure: A = CASM_DIAG_STREAM_STATE_FAILED, C set
; Clobbers:  A
; ---------------------------------------------------------------------------
listingReplayReset:
    lda CasmListingState
    cmp #CASM_LISTING_STATE_COMPLETE
    beq lrrOk
    lda #CASM_DIAG_STREAM_STATE_FAILED
    sec
    rts
lrrOk:
    lda #0
    sta CasmListingReplayIndexLo
    sta CasmListingReplayIndexHi
    lda #CASM_DIAG_NONE
    clc
    rts

; ---------------------------------------------------------------------------
; listingReplayNext
; Read one metadata record into CasmVmmBuffer and advance the replay cursor.
; Repeat-stable at EOF: calling again after CASM_STREAM_EOF returns
; CASM_STREAM_EOF again, with no further transfer and the cursor unchanged.
;
; Inputs:    listingReplayReset already called at least once
; Outputs:   Data: A = CASM_STREAM_DATA, C clear; CasmVmmBuffer holds the
;            16-byte record at the pre-advance cursor position; cursor
;            advanced by one record
;            EOF: A = CASM_STREAM_EOF, C clear; cursor unchanged
;            Fail: A = CASM_DIAG_VMM_TRANSFER_FAILED, C set; cursor unchanged
; Clobbers:  A, X, Y, CasmVmmBuffer, CasmVmmOffLo/OffHi, CasmIoLenLo/Hi
; ---------------------------------------------------------------------------
listingReplayNext:
    lda CasmListingReplayIndexLo
    cmp CasmListingRecordCountLo
    lda CasmListingReplayIndexHi
    sbc CasmListingRecordCountHi
    bcc lrnHaveRecord            ; replay index < record count
    lda #CASM_STREAM_EOF
    clc
    rts
lrnHaveRecord:
    lda CasmListingReplayIndexLo
    sta CasmVmmOffLo
    lda CasmListingReplayIndexHi
    sta CasmVmmOffHi
    ldx #4
lrnShift:
    asl CasmVmmOffLo
    rol CasmVmmOffHi
    dex
    bne lrnShift

    lda #CASM_LISTING_META_REC_SIZE
    sta CasmIoLenLo
    lda #0
    sta CasmIoLenHi
    ldx CasmListingMetaVmmSlot
    jsr vmmWindowRead
    bcs lrnFail

    inc CasmListingReplayIndexLo
    bne lrnDone
    inc CasmListingReplayIndexHi
lrnDone:
    lda #CASM_STREAM_DATA
    clc
    rts
lrnFail:
    lda #CASM_DIAG_VMM_TRANSFER_FAILED
    sec
    rts
